"""Invented wording and generated bytes; no game text or binary fixtures."""
import unittest

from audit_scenario import audit, check_expectations, check_revision, effective_entries
from test_scenario_text import fixture
from test_school_life import fixture as opening_fixture


class AuditTests(unittest.TestCase):
    def test_new_entries_and_exact_reviewed_correction(self):
        before = {'bank_entries': {'0': {'0': ['Hello.']}}}
        after = {'bank_entries': {'0': {'0': ['Good morning.']}, '1': {'1': ['Her turn.']}}}
        correction = {'entry': [0, 0], 'before': ['Hello.'], 'after': ['Good morning.']}
        report = audit(fixture(), before, after, [correction],
                       [{'entry': [1, 1], 'contains': ['her'], 'excludes': ['his']}])
        self.assertEqual((report['new_entries'], report['reviewed_corrections']), (1, 1))
        self.assertTrue(report['all_pointer_contents_checked'])
        self.assertNotIn('Good morning', str(report))

    def test_rejects_unreviewed_change_removal_and_stale_correction(self):
        before = {'bank_entries': {'0': {'0': ['Hello.']}}}
        after = {'bank_entries': {'0': {'0': ['Bye.']}}}
        correction = {'entry': [0, 0], 'before': ['Hello.'], 'after': ['Bye.']}
        for new, corrections in [(after, []), ({}, []), (before, [correction]), (after, [correction, correction])]:
            with self.subTest(new=new, corrections=corrections), self.assertRaises(ValueError):
                audit(fixture(), before, new, corrections)

    def test_legacy_dialogue_is_included_and_overrides_require_review(self):
        opening = {'dialogue': {'0': ['Hello.']}, 'bank_entries': {'2': {'1': ['Menu']}}}
        before = {'opening': opening}
        after = {'opening': opening, 'bank_entries': {'1': {'0': ['Her turn.']}}}
        self.assertEqual(effective_entries(before)[1, 0], ['Hello.'])
        self.assertEqual(effective_entries(before)[2, 1], ['Menu'])
        with self.assertRaises(ValueError):
            check_revision(before, after, [])
        check_revision(before, after, [{'entry': [1, 0], 'before': ['Hello.'], 'after': ['Her turn.']}])
        with self.assertRaises(ValueError):
            check_revision(before, {}, [])

    def test_word_checks_do_not_match_substrings_or_guess_gender(self):
        entries = {(0, 0): ['There is a gate.'], (1, 0): ['Her turn.']}
        check_expectations(entries, [{'entry': [0, 0], 'excludes': ['he', 'her']}])
        for expectation in [{'entry': [1, 0], 'contains': ['him']},
                            {'entry': [1, 0], 'excludes': ['her']},
                            {'entry': [9, 0], 'contains': ['him']}]:
            with self.assertRaises(ValueError):
                check_expectations(entries, [expectation])

    def test_legacy_opening_override_round_trips_through_both_patchers(self):
        source = opening_fixture().ljust(333824, b'\0')
        opening = {'dialogue': {'56': ['Practice.']}, 'choices': ['A'] * 7,
                   'dialogue_counts': [57, 57], 'runtime_pairs': True}
        before = {'opening': opening}
        after = {'opening': opening, 'bank_entries': {'1': {'56': ['Her turn.']}}}
        report = audit(source, before, after,
                       [{'entry': [1, 56], 'before': ['Practice.'], 'after': ['Her turn.']}])
        self.assertEqual(report['reviewed_corrections'], 1)
        self.assertTrue(report['all_pointer_contents_checked'])

    def test_variable_loss_and_nonexistent_entries_are_rejected(self):
        for after in [{'bank_entries': {'0': {'1': ['Date omitted.']}}},
                      {'bank_entries': {'7': {'99': ['Hello.']}}}]:
            with self.subTest(after=after), self.assertRaises(ValueError):
                audit(fixture(), {}, after)


if __name__ == '__main__':
    unittest.main()
